cd /app && python3 << 'EOF'
import csv
from collections import defaultdict
rows = list(csv.DictReader(open('input/dissertation_section_log.csv')))
by_id = defaultdict(list)
for r in rows: by_id[r['section_id']].append(r)
audited = {sid: sorted(rs,key=lambda x:int(x['revision']))[-1] for sid,rs in by_id.items()}
PW=24.2
print("=== Landscape annexes: exception status ===")
for sid,r in audited.items():
    if r['section_type']=='annex' and r['orientation']=='landscape':
        wt=float(r['widest_table_cm'])
        print(f"{sid}: widest_table={wt}, oversized(>{PW})={wt>PW}, exception={wt>PW}, inner={r['margin_inner_cm']}")
print("\n=== Non-annex or non-landscape with wide tables ===")
for sid,r in audited.items():
    if r['orientation']=='landscape' and r['section_type']!='annex':
        print(f"{sid}: type={r['section_type']}, orientation=landscape -> exception N/A (not annex), outer={r['margin_outer_cm']}")
    if r['section_type']=='annex' and r['orientation']!='landscape':
        print(f"{sid}: type=annex, orientation={r['orientation']} -> exception N/A (not landscape), outer={r['margin_outer_cm']}")
EOF
